def trace_bfs_all_depths(adjacency, start, max_depth=6):
    from collections import deque

    distances = {start: 0}
    queue = deque([start])
    depth_nodes = {0: [start]}

    while queue:
        node = queue.popleft()
        current_dist = distances[node]

        if current_dist >= max_depth:
            continue

        for neighbor in adjacency.get(node, set()):
            if neighbor not in distances:
                distances[neighbor] = current_dist + 1
                queue.append(neighbor)
                dist = current_dist + 1
                if dist not in depth_nodes:
                    depth_nodes[dist] = []
                depth_nodes[dist].append(neighbor)

    return distances, depth_nodes

distances, depth_nodes = trace_bfs_all_depths(adjacency, '8f14e45fce', 6)

print("All depths:")
for d in sorted(depth_nodes.keys()):
    print(f"Depth {d}: {sorted(depth_nodes[d])}")

print(f"\nMaximum depth reached: {max(distances.values())}")
print(f"Nodes at depth 4: {sorted(depth_nodes.get(4, []))}")
